CREATE SCHEMA IF NOT EXISTS realcloset_studio;
REVOKE ALL ON SCHEMA realcloset_studio FROM PUBLIC;
SET LOCAL search_path TO realcloset_studio;
CREATE TABLE IF NOT EXISTS looks(id TEXT PRIMARY KEY, owner TEXT NOT NULL, payload TEXT NOT NULL, share TEXT UNIQUE, rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS profiles(owner TEXT PRIMARY KEY, payload TEXT NOT NULL, rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, owner TEXT NOT NULL, actor TEXT NOT NULL, kind TEXT NOT NULL, look_id TEXT, created_at TEXT NOT NULL, read INTEGER DEFAULT 0, rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS polls(token TEXT PRIMARY KEY, owner TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS poll_votes(token TEXT, visitor TEXT, choice INTEGER, PRIMARY KEY(token,visitor), rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS state(owner TEXT PRIMARY KEY, payload TEXT NOT NULL, rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS public_items(id TEXT, owner TEXT, payload TEXT NOT NULL, PRIMARY KEY(id,owner), rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS reactions(share TEXT, visitor TEXT, kind TEXT, value TEXT, PRIMARY KEY(share,visitor,kind), rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS replies(id TEXT PRIMARY KEY, share TEXT, visitor TEXT, name TEXT, text TEXT, rowid BIGSERIAL UNIQUE);
CREATE TABLE IF NOT EXISTS search_posts(look_id TEXT PRIMARY KEY REFERENCES looks(id) ON DELETE CASCADE, owner TEXT NOT NULL, public INTEGER NOT NULL, published_at TEXT NOT NULL, rowid BIGSERIAL UNIQUE);
CREATE INDEX IF NOT EXISTS search_posts_public_date ON search_posts(public,published_at DESC,look_id DESC);
CREATE TABLE IF NOT EXISTS look_tags(look_id TEXT REFERENCES looks(id) ON DELETE CASCADE, tag TEXT NOT NULL, PRIMARY KEY(look_id,tag), rowid BIGSERIAL UNIQUE);
CREATE INDEX IF NOT EXISTS look_tags_prefix ON look_tags(tag,look_id);
CREATE TABLE IF NOT EXISTS profile_search(owner TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL, rowid BIGSERIAL UNIQUE);
CREATE INDEX IF NOT EXISTS profile_search_prefix ON profile_search(name_key,owner);
CREATE INDEX IF NOT EXISTS looks_owner ON looks(owner);
